kit.contenido:
[
  {
    "name": "ver_horarios_libres",
    "description": "Devuelve los horarios libres para un servicio en una fecha o rango de fechas, según la agenda real del negocio. Úsala siempre antes de ofrecer o confirmar un turno. Nunca ofrezcas un horario que no haya salido de esta herramienta.",
    "input_schema": {
      "type": "object",
      "properties": {
        "servicio": {
          "type": "string",
          "description": "Nombre del servicio tal como figura en la lista del negocio."
        },
        "fecha_desde": {
          "type": "string",
          "description": "Fecha de inicio en formato AAAA-MM-DD."
        },
        "fecha_hasta": {
          "type": "string",
          "description": "Fecha de fin en formato AAAA-MM-DD. Igual a fecha_desde si es un solo día."
        },
        "franja": {
          "type": "string",
          "enum": [
            "manana",
            "tarde",
            "cualquiera"
          ],
          "description": "Preferencia del cliente, si la dijo."
        }
      },
      "required": [
        "servicio",
        "fecha_desde",
        "fecha_hasta"
      ]
    }
  },
  {
    "name": "crear_turno",
    "description": "Reserva un turno. Úsala solo después de repetirle al cliente día, hora y servicio y de recibir un sí explícito. El sistema vuelve a chequear que el horario siga libre; si ya no lo está, devuelve un error y tienes que ofrecer otros horarios con ver_horarios_libres.",
    "input_schema": {
      "type": "object",
      "properties": {
        "servicio": {
          "type": "string",
          "description": "Nombre del servicio."
        },
        "inicio": {
          "type": "string",
          "description": "Fecha y hora de inicio en formato AAAA-MM-DDTHH:MM, hora local del negocio."
        },
        "nombre_cliente": {
          "type": "string",
          "description": "Nombre con el que el cliente quiere figurar en el turno."
        },
        "acepto_recordatorio": {
          "type": "boolean",
          "description": "true solo si el cliente dijo que sí a recibir un recordatorio por WhatsApp."
        }
      },
      "required": [
        "servicio",
        "inicio",
        "nombre_cliente",
        "acepto_recordatorio"
      ]
    }
  },
  {
    "name": "buscar_turnos_del_cliente",
    "description": "Devuelve los turnos futuros del cliente que está escribiendo, identificado por su número de WhatsApp. Úsala antes de cambiar o cancelar un turno.",
    "input_schema": {
      "type": "object",
      "properties": {},
      "required": []
    }
  },
  {
    "name": "cancelar_turno",
    "description": "Cancela un turno del cliente que está escribiendo. Úsala solo después de confirmar con el cliente cuál turno cancela y de recibir un sí explícito. Para cambiar un turno: primero crea el nuevo con crear_turno y recién después cancela el viejo.",
    "input_schema": {
      "type": "object",
      "properties": {
        "id_turno": {
          "type": "string",
          "description": "Identificador devuelto por buscar_turnos_del_cliente."
        }
      },
      "required": [
        "id_turno"
      ]
    }
  },
  {
    "name": "derivar_a_persona",
    "description": "Pasa la conversación a una persona del equipo y deja de responder automáticamente en este chat hasta que el equipo lo libere. Úsala cuando el cliente pide hablar con alguien, está enojado, reclama un cobro, pregunta algo que no está en la información del negocio o cuando no estás seguro.",
    "input_schema": {
      "type": "object",
      "properties": {
        "motivo": {
          "type": "string",
          "enum": [
            "pide_persona",
            "reclamo",
            "cobro",
            "sin_informacion",
            "otro"
          ],
          "description": "Por qué se deriva."
        },
        "resumen": {
          "type": "string",
          "description": "Dos o tres líneas con lo que pidió el cliente y lo que ya se le respondió, para que la persona no tenga que leer todo el chat."
        }
      },
      "required": [
        "motivo",
        "resumen"
      ]
    }
  }
]
